// n8n Code node "Auth Summary" (run once for all items). Globals: $, $json.
// The collector could not list businesses (login needed, selector change, collector down): record a FAILED run.
const code = $json.status === 'AUTH_REQUIRED' ? 'AUTH_REQUIRED' : $json.status === 'OK' ? 'BUSINESS_NOT_FOUND' : ($json.error_code || 'NETWORK_ERROR');
const message = String($json.error_message || ($json.error && $json.error.message) || (code === 'BUSINESS_NOT_FOUND' ? 'no managed businesses found' : code));
const now = new Date().toISOString();
const summary = { businesses_checked: 0, reviews_scanned: 0, new_reviews: 0, positive_reviews: 0, neutral_reviews: 0, negative_reviews: 0, urgent_reviews: 0, errors: 1, started_at: $('Config').first().json.startedAt, completed_at: now };
return [{ json: { status: 'FAILED', error_code: code, message, summary, errors: [{ business: null, error_code: code, error_message: message, screenshot: $json.screenshot || null, timestamp: now }] } }];

// n8n Code node "Flatten Reviews" (run once for all items). Globals: $, $input, $json.
// Joins the collector response with the Supabase business ids and emits one item per review.
const r = $input.first().json;
const biz = $('Split Businesses').all().map((i) => i.json);
const ups = $('Upsert Business').all().map((i) => i.json);
const msg = (e) => String((e && e.message) || e || '');
const idMap = {};
const errors = [];
for (const u of ups) {
  if (u.id) idMap[u.external_business_id] = u.id;
  else errors.push({ business: null, error_code: 'DATABASE_ERROR', error_message: msg(u.error), screenshot: null });
}
const nameOf = Object.fromEntries(biz.map((b) => [b.business_identifier, b.business_name]));
let fatal = false;
let reviews = [];
if (r.error) { fatal = true; errors.push({ business: null, error_code: 'NETWORK_ERROR', error_message: msg(r.error), screenshot: null }); }
else if (r.status !== 'OK') { fatal = true; errors.push({ business: null, error_code: r.error_code || 'UNKNOWN_ERROR', error_message: r.error_message || r.status, screenshot: r.screenshot || null }); }
else { reviews = r.reviews || []; for (const e of r.errors || []) errors.push({ business: e.business, error_code: e.error_code, error_message: e.error_message, screenshot: null }); } // per-property failures
const out = [];
const t0 = Date.now();
for (const x of reviews) {
  if (!idMap[x.business_identifier]) {
    errors.push({ business: x.business_identifier, error_code: 'BUSINESS_NOT_FOUND', error_message: 'review for a business missing from the locations list', screenshot: null });
    continue;
  }
  // Feed is newest first; 1 ms steps keep that order in collected_at, the dashboard's tie-break inside one day.
  out.push({ json: { ...x, platform: x.platform || 'google', business_id: idMap[x.business_identifier], business_name: nameOf[x.business_identifier], collected_at: new Date(t0 - out.length).toISOString() } });
}
// Sentinel keeps the review loop (and the final summary) running when nothing was scraped.
if (!out.length) out.push({ json: { _sentinel: true, review_hash: 'none' } });
out[0].json._stats = { businesses: biz.length, scanned: r.scanned || 0, errors, fatal };
return out;

// n8n Code node "Validate AI" (run once for each item). Globals: $, $json.
// Never trust model output: parse, check enums, clamp numbers, drop unknown categories, enforce the rating->priority floor.
const r = $('Review Loop').item.json;
const CATS = ['ROOM','CLEANLINESS','STAFF','SERVICE','LOCATION','PRICE','BREAKFAST','FOOD','FACILITIES','WIFI','NOISE','CHECKIN','CHECKOUT','BOOKING','PAYMENT','PARKING','SECURITY','AIR_CONDITIONER','BATHROOM','BED','VIEW','POOL','RESTAURANT','OTHER'];
const SENT = ['positive', 'neutral', 'negative'];
const PRI = ['low', 'medium', 'high', 'urgent'];
const fail = (m) => ({ json: { ...r, ai_ok: false, ai_error: m } });
if ($json.error) return fail(String($json.error.message || $json.error));
let a;
try { a = JSON.parse($json.candidates[0].content.parts.map((p) => p.text).join('')); } catch (e) { return fail('invalid JSON from model'); }
if (!SENT.includes(a.sentiment) || !PRI.includes(a.priority)) return fail('schema violation');
const floor = r.rating <= 2 ? 2 : r.rating === 3 ? 1 : 0; // rating sets the minimum priority
const priority = PRI[Math.max(PRI.indexOf(a.priority), floor)];
const clamp = (n, lo, hi) => Math.max(lo, Math.min(hi, Number(n) || 0));
return { json: {
  ...r, ai_ok: true,
  sentiment: a.sentiment,
  sentiment_score: Math.round(clamp(a.sentiment_score, -100, 100)),
  category: (Array.isArray(a.category) ? a.category : []).filter((c) => CATS.includes(c)),
  priority,
  requires_attention: Boolean(a.requires_attention) || priority === 'urgent',
  summary: String(a.summary || ''),
  key_points: Array.isArray(a.key_points) ? a.key_points.map(String) : [],
  suggested_action: String(a.suggested_action || ''),
  language: String(a.language || 'unknown'),
  reply_draft: r.has_owner_reply ? '' : String(a.reply_draft || '').trim().slice(0, 3500), // human moderates it later
  ai_confidence: clamp(a.ai_confidence, 0, 1),
  analyzed_at: new Date().toISOString(),
} };

// n8n Code node "Run Summary" (run once for all items). Globals: $, $input.
// Fires when the review loop is done; its input is every item that looped back (saved, skipped or failed).
const cfg = $('Config').first().json;
const stats = $('Flatten Reviews').first().json._stats;
const items = $input.all().map((i) => i.json);
const saved = items.filter((r) => r.id && r.sentiment);
const aiFail = items.filter((r) => r.ai_ok === false).length;
const dbFail = items.filter((r) => r.error).length;
const now = new Date().toISOString();
const errors = stats.errors.map((e) => ({ ...e, timestamp: now }));
if (aiFail) errors.push({ business: null, error_code: 'AI_ERROR', error_message: aiFail + ' review(s) not analyzed; retried next run', screenshot: null, timestamp: now });
if (dbFail) errors.push({ business: null, error_code: 'DATABASE_ERROR', error_message: dbFail + ' review(s) failed to save/check', screenshot: null, timestamp: now });
const count = (f) => saved.filter(f).length;
const summary = {
  platform: cfg.platform || 'google',
  businesses_checked: stats.businesses,
  reviews_scanned: stats.scanned,
  new_reviews: saved.length,
  positive_reviews: count((r) => r.sentiment === 'positive'),
  neutral_reviews: count((r) => r.sentiment === 'neutral'),
  negative_reviews: count((r) => r.sentiment === 'negative'),
  urgent_reviews: count((r) => r.priority === 'urgent'),
  errors: errors.length,
  started_at: cfg.startedAt,
  completed_at: now,
};
const status = stats.fatal ? 'FAILED' : errors.length ? 'PARTIAL' : 'SUCCESS';
return [{ json: { status, summary, errors, error_code: errors.length ? errors[0].error_code : null, message: errors.map((e) => e.error_code + ': ' + e.error_message).join('\n') } }];
